(function(root,factory){const model=factory();if(typeof module==='object'&&module.exports)module.exports=model;else root.KnowledgeModel=model;})(typeof globalThis!=='undefined'?globalThis:this,()=>{
 const fields=[['problem','해결하려던 문제'],['approach','시도한 방법'],['result','결과와 효과'],['lessons','시행착오와 배운 점'],['conditions','재사용 조건'],['nextSteps','남은 문제와 후속 제안']];
 const types={predecessor:'선행 과제',successor:'후속 과제',related:'유사·관련 과제',reuses:'결과를 가져온 과제'};
 const reverse={predecessor:'후속 과제',successor:'선행 과제',related:'유사·관련 과제',reuses:'내 결과를 활용한 과제'};
 const empty=()=>({version:1,status:'draft',...Object.fromEntries(fields.map(([key])=>[key,''])),artifacts:[],relations:[],sourceEvidence:[]});
 function safeUrl(value){try{const u=new URL(value);return ['https:','http:'].includes(u.protocol)&&!u.username&&!u.password;}catch{return false;}}
 function validate(value,id,projects){const errors=[];if(!['draft','published'].includes(value.status))errors.push('저장 상태를 확인해 주세요.');for(const [key,label] of fields){if(typeof value[key]!=='string'||value[key].length>10000)errors.push(`${label}은 10,000자 이내로 입력해 주세요.`);if(value.status==='published'&&!String(value[key]||'').trim()&&['problem','approach','result','lessons','conditions'].includes(key))errors.push(`${label}: 내용을 입력한 뒤 공유해 주세요.`);}if((value.artifacts||[]).length>20)errors.push('결과물은 20개까지 연결할 수 있습니다.');for(const a of value.artifacts||[])if(!a.title?.trim()||a.title.length>200||!safeUrl(a.url)||a.url.length>2000)errors.push('결과물 이름과 http(s) 문서 주소를 확인해 주세요.');const seen=new Set();for(const r of value.relations||[]){if(!types[r.type]||!r.projectId||r.projectId===id)errors.push('관련 과제와 관계를 확인해 주세요.');if(projects&&!projects.some(p=>p.id===r.projectId))errors.push('연결할 과제를 불러오거나 존재 여부를 확인해 주세요.');if(seen.has(r.projectId))errors.push('동일 과제는 한 번만 연결할 수 있습니다.');seen.add(r.projectId);}if(seen.size>100)errors.push('관련 과제는 100개까지 연결할 수 있습니다.');return errors;}
 function connections(project,projects){const result=new Map();for(const r of project._knowledge?.relations||[])result.set(r.projectId,{id:r.projectId,label:types[r.type]||r.type,outgoing:true});for(const p of projects)for(const r of p._knowledge?.relations||[])if(r.projectId===project.id&&!result.has(p.id))result.set(p.id,{id:p.id,label:reverse[r.type],outgoing:false});return [...result.values()].map(r=>({...r,project:projects.find(p=>p.id===r.id)}));}
 function search(projects,{query='',year='',tech='',team='',published=false}={}){const words=query.toLocaleLowerCase().trim().split(/\s+/).filter(Boolean);return projects.filter(p=>{const k=p._knowledge||{},text=[p.title,p.team,p.po,p.pm,p.members,...(p.tech||[]),...fields.map(([key])=>k[key]),...(k.artifacts||[]).map(a=>a.title)].join(' ').toLocaleLowerCase();return words.every(w=>text.includes(w))&&(!year||p.startDate?.slice(0,4)<=year&&p.endDate?.slice(0,4)>=year)&&(!tech||(p.tech||[]).includes(tech))&&(!team||p.team===team)&&(!published||k.status==='published');});}
 return {fields,types,empty,safeUrl,validate,connections,search};
});
